dtsPropsFor.Avatar:
/** Person's display name — its initials are shown when no emoji is given. */
name: string;
/** Emoji avatar; falls back to initials when null/undefined. */
emoji?: string | null;

dtsPropsFor.ArtifactChips:
/** Section heading (e.g. "Code & links this channel keeps referencing"). */
title: string;
artifacts: Array<{ ref: string; kind: 'code' | 'link'; mentions: number; channelId: string; channelName: string }>;
onOpenChannel: (channelId: string) => void;

dtsPropsFor.ThreadCard:
channelName: string;
/** Optional top-right adornment (e.g. a timestamp or count). */
corner?: React.ReactNode;
onClick: () => void;
children: React.ReactNode;

dtsPropsFor.UserHover:
userId: string;
name: string;
/** The element representing the person; hovering reveals a profile card. */
children: React.ReactNode;

dtsPropsFor.Message:
message: {
  id: string;
  channelId: string;
  authorId: string;
  authorName: string;
  authorAvatarEmoji: string | null;
  parentMessageId: string | null;
  body: string;
  createdAt: string;
  replyCount: number;
  reactions: Array<{ emoji: string; count: number; mine: boolean }>;
  attachments: Array<{ id: string; kind: 'image' | 'video' | 'audio' | 'file'; name: string; url: string }>;
};
/** Consecutive message from the same author — hides the avatar/header. */
compact?: boolean;
onOpenThread?: (root: MessageProps['message']) => void;

dtsPropsFor.Composer:
channelId: string;
parentMessageId?: string;
placeholder: string;
/** Slash-command quick actions surfaced as you type "/". */
commands?: Array<{ name: string; hint: string; run: (arg: string) => void }>;

dtsPropsFor.Sidebar:
me: { id: string; name: string; title: string | null; team: string | null; avatarEmoji: string | null; statusEmoji: string | null; statusText: string | null };
channels: Array<{ id: string; name: string; type: 'public' | 'private' | 'dm'; topic: string | null; archivedAt: string | null; pinned: number | null; unreadCount: number; dmPartnerNames?: string[]; dmPartnerIds?: string[] }>;
users: SidebarProps['me'][];
online: Set<string>;
activeId: string | null;
homeActive: boolean;
taskActive: boolean;
peopleActive: boolean;
space: { name: string; invite: string; connectedPeers: number } | null;
liveCalls: Set<string>;
onHome: () => void;
onTask: () => void;
onPeople: () => void;
onOpenSpace: () => void;
onSelect: (id: string) => void;
onNewGroup: () => void;
onNewChannel: () => void;
onTogglePin: (channelId: string, pinned: boolean) => void;
onReorderPins: (channelIds: string[]) => void;
